# Generated by HCW 0.1.0 on 2026 11 12
"""
Add card and crypto accounts to the HOPE Individual checker.

The HOPE Account fieldset is attached to the checker once per account type, with the `{type}_`
prefix, so the `card_*` and `crypto_*` fields of imported accounts were reported as alien values.
"""

from typing import Final

from django.db import transaction
from hope_flex_fields.models import DataChecker, DataCheckerFieldset, Fieldset
from packaging.version import Version

from country_workspace.contrib.hope.constants import ACCOUNT_FIELDSET_NAME, INDIVIDUAL_CHECKER_NAME

_script_for_version = Version("0.1.0")

NEW_ACCOUNT_TYPES: Final[tuple[str, ...]] = ("card", "crypto")


@transaction.atomic
def forward() -> None:
    checker = DataChecker.objects.get(name=INDIVIDUAL_CHECKER_NAME)
    fieldset = Fieldset.objects.get(name=ACCOUNT_FIELDSET_NAME)
    for account_type in NEW_ACCOUNT_TYPES:
        DataCheckerFieldset.objects.get_or_create(checker=checker, fieldset=fieldset, prefix=f"{account_type}_")


@transaction.atomic
def backward() -> None:
    DataCheckerFieldset.objects.filter(
        checker__name=INDIVIDUAL_CHECKER_NAME,
        fieldset__name=ACCOUNT_FIELDSET_NAME,
        prefix__in=[f"{account_type}_" for account_type in NEW_ACCOUNT_TYPES],
    ).delete()


class Scripts:
    requires = []
    operations = [(forward, backward)]
